contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 fund, uint256 value, address adr) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (fund) + (value)); require(fund <= 1000000000000000000000000000000); require(value <= 1000000000000000000000000000000);
        require(address(this).balance >= fund + value);
        require(fund < 2**255);
        require(adr.code.length == 0);
        require(adr != address(c));
        require(adr != address(this));
        // fund c by sending Ether to itself through Command
        c.Command{value: fund}(address(c), ""); if (__ESBMC_reverted()) return;
        uint256 balBefore = address(c).balance;
        require(value < balBefore);
        uint256 adrBefore = adr.balance;
        bool reverted;
        c.multiplicate{value: value}(adr); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(!reverted && address(c).balance == balBefore + value && adr.balance == adrBefore);
    }
    receive() external payable {}
    fallback() external payable {}
}

