pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(uint256 fund, uint256 value, address adr) internal {
        fund = bound(fund, 0, 1000000000000000000000000000000);
        value = bound(value, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= fund + value);
        vm.assume(fund < 2**255);
        vm.assume(adr.code.length == 0);
        vm.assume(adr != address(c));
        vm.assume(adr != address(this));
        try c.Command{value: fund}(address(c), "") {} catch { return; }
        uint256 balBefore = address(c).balance;
        vm.assume(value < balBefore);
        uint256 adrBefore = adr.balance;
        bool reverted;
        try c.multiplicate{value: value}(adr) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted && address(c).balance == balBefore + value && adr.balance == adrBefore);
    }

    function testFuzz_run(uint256 fund, uint256 value, address adr) public {
        vm.assume(adr.code.length == 0 && uint160(adr) > 0xffff && adr != address(this) && adr != address(c) && adr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && adr != 0x000000000000000000636F6e736F6c652e6c6f67 && adr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && adr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(fund, value, adr);
    }

    receive() external payable {}

    fallback() external payable {}
}
